reference_solution:
def deck_order_for_increasing_reveal(deck):
    from collections import deque
    queue=deque()
    for value in sorted(deck,reverse=True):
        if queue:queue.appendleft(queue.pop())
        queue.appendleft(value)
    return list(queue)

